// Style Sheet CSS
import styles from "./mangas.module.css";

import { MangaCard } from "@/components/MangaCard/page";
import { getMangas } from "@/lib/catalog";

async function MangasPage() {
  const mangas = await getMangas().catch((error) => {
    console.error("Falha ao carregar mangás:", error);
    return [];
  });
  return (
    <div className={styles.page}>
      <main className={styles.mangasContainer}>
        <MangaCard pageTitle="Mangás cadastrados" mangas={mangas} />
      </main>
    </div>
  );
}

export default MangasPage;
